import numpy as np

# Define the formulas for the 8 arrangements (1-based indexing i, j in {1..7})

def A1(i, j):
    return i + 7 * (j - 1)

def A1R(i, j):
    return (8 - i) + 7 * (j - 1)

def A1C(i, j):
    return i + 7 * (7 - j)

def A1RC(i, j):
    return (8 - i) + 7 * (7 - j)

def A2(i, j):
    return 7 * (i - 1) + j

def A2R(i, j):
    return 7 * (7 - i) + j

def A2C(i, j):
    return 7 * (i - 1) + (8 - j)

def A2RC(i, j):
    return 7 * (7 - i) + (8 - j)

# Generate the matrices
N = 7
I = np.arange(1, N + 1)
J = np.arange(1, N + 1)
I_mesh, J_mesh = np.meshgrid(I, J, indexing='ij')

M1 = np.array([[A1(i, j) for j in J] for i in I])
M1R = np.array([[A1R(i, j) for j in J] for i in I])
M1C = np.array([[A1C(i, j) for j in J] for i in I])
M1RC = np.array([[A1RC(i, j) for j in J] for i in I])

M2 = np.array([[A2(i, j) for j in J] for i in I])
M2R = np.array([[A2R(i, j) for j in J] for i in I])
M2C = np.array([[A2C(i, j) for j in J] for i in I])
M2RC = np.array([[A2RC(i, j) for j in J] for i in I])

matrices = {
    'A1': M1, 'A1R': M1R, 'A1C': M1C, 'A1RC': M1RC,
    'A2': M2, 'A2R': M2R, 'A2C': M2C, 'A2RC': M2RC
}

# Check for equality between all pairs
equal_pairs = []
keys = list(matrices.keys())

for i in range(len(keys)):
    for j in range(i + 1, len(keys)):
        key1 = keys[i]
        key2 = keys[j]

        # Check if matrices are numerically identical
        if np.array_equal(matrices[key1], matrices[key2]):
            equal_pairs.append((key1, key2))

print("Identical Pairs Found:")
for pair in equal_pairs:
    print(f"({pair[0]}, {pair[1]})")
